/**
 * Availability zone mapping utilities for subnet translation.
 * Maps AWS AZs to Azure zone numbers and GCP zone suffixes.
 *
 * @module structural/subnet-az-mapper
 * @generated by code-generator (TASK-NET-002)
 */

import { transformRegion } from '../direct/attribute-transformer.js';

// ---------------------------------------------------------------------------
// AZ suffix extraction
// ---------------------------------------------------------------------------

/**
 * Extracts the trailing letter suffix from an AWS AZ string.
 * e.g. "us-east-1a" -> "a", "eu-west-2c" -> "c"
 *
 * Returns undefined if no valid suffix is found.
 */
export function extractAzSuffix(az: string): string | undefined {
  if (typeof az !== 'string' || az.length === 0) return undefined;
  const match = /([a-z])$/.exec(az);
  return match ? match[1] : undefined;
}

// ---------------------------------------------------------------------------
// Azure zone mapping
// ---------------------------------------------------------------------------

/**
 * Maps an AWS AZ to an Azure availability zone number (1-3).
 * Azure zones are numbered 1-3; we map a->1, b->2, c->3, d->1, etc.
 *
 * Returns undefined if the AZ has no recognisable suffix.
 */
export function mapAzToAzureZone(az: string): number | undefined {
  const suffix = extractAzSuffix(az);
  if (!suffix) return undefined;
  return ((suffix.charCodeAt(0) - 97) % 3) + 1;
}

// ---------------------------------------------------------------------------
// GCP zone mapping
// ---------------------------------------------------------------------------

/**
 * Maps an AWS AZ to a GCP zone string (e.g. "us-east1-a").
 * Derives the AWS region by stripping the trailing letter suffix, maps it
 * to a GCP region via transformRegion, then appends the suffix letter.
 *
 * AWS AZs append the letter directly without a hyphen (e.g. "us-east-1a"),
 * so we slice off the last character to recover the region.
 *
 * Returns undefined if the AZ has no recognisable suffix.
 */
export function mapAzToGcpZone(az: string): string | undefined {
  const suffix = extractAzSuffix(az);
  if (!suffix) return undefined;

  // Strip the trailing letter to recover the AWS region string.
  const awsRegion = az.slice(0, -1);
  const gcpRegion = transformRegion('gcp', awsRegion);
  return `${gcpRegion}-${suffix}`;
}
